+        ),
+      },
+    ]),
+  ).toEqual(Option.none);
+});
+
+test("ファイルが不正な間は、まとめて置き直せない", () => {
+  // 凍結しなければ通る指定にして、凍結のガードを消した実装を落とす
+  expect(
